package server

import (
	"fmt"
	"html"
	"html/template"
	"net/http"
	"strconv"

	"github.com/matteocontrini/notedimatteo/internal/db"
)

const postsPerPage = 20

type postView struct {
	db.Post
	HTML     template.HTML
	ShowDate bool
	CanEdit  bool
}

func newPostView(post db.Post, showDate, canEdit bool) postView {
	view := postView{Post: post, ShowDate: showDate, CanEdit: canEdit}
	if post.CachedHTML != nil {
		// The cache only contains HTML generated by the Markdown renderer
		view.HTML = template.HTML(*post.CachedHTML)
	} else {
		// Temporary until the Markdown renderer is ported
		view.HTML = template.HTML("<pre>" + html.EscapeString(post.Body) + "</pre>")
	}
	return view
}

type postGroup struct {
	Heading string
	Posts   []postView
}

// groupByDay groups posts, already sorted, by their day in Rome's time zone.
func groupByDay(posts []postView) []postGroup {
	var groups []postGroup
	lastKey := ""
	for _, post := range posts {
		key := dateKey(post.Timestamp())
		if len(groups) == 0 || key != lastKey {
			groups = append(groups, postGroup{Heading: formatDate(post.Timestamp())})
			lastKey = key
		}
		last := &groups[len(groups)-1]
		last.Posts = append(last.Posts, post)
	}
	return groups
}

// pageNumber reads the page query parameter. Invalid values mean the first page.
func pageNumber(r *http.Request) int {
	page, err := strconv.Atoi(r.URL.Query().Get("page"))
	if err != nil || page < 1 {
		return 1
	}
	return page
}

type homeData struct {
	Page
	Groups     []postGroup
	Pagination pagination
}

func (s *Server) home(w http.ResponseWriter, r *http.Request) error {
	page, err := s.newPage(r, Meta{})
	if err != nil {
		return err
	}

	current := pageNumber(r)
	total, err := s.store.CountPublishedPosts(r.Context())
	if err != nil {
		return err
	}
	posts, err := s.store.PublishedPosts(r.Context(), postsPerPage, (current-1)*postsPerPage)
	if err != nil {
		return err
	}

	views := make([]postView, 0, len(posts))
	for _, post := range posts {
		views = append(views, newPostView(post, false, page.IsLoggedIn))
	}

	totalPages := (total + postsPerPage - 1) / postsPerPage

	return s.render(w, http.StatusOK, "home", homeData{
		Page:       page,
		Groups:     groupByDay(views),
		Pagination: newPagination(r.URL.Path, current, totalPages),
	})
}

func (s *Server) healthz(w http.ResponseWriter, r *http.Request) error {
	if err := s.store.Ping(r.Context()); err != nil {
		return fmt.Errorf("ping database: %w", err)
	}

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, err := w.Write([]byte("ok\n"))
	return err
}
